// repoRoot is carved out of the internal pkg/pricing/consumers_test.go
// by scripts/make-public-export.sh: that file is machine-pinned to private
// delivery-program records and stays internal (TP-10 precedent), but kept
// exported pricing tests still use the helper. Do not edit this file;
// the internal file is the single source of truth.

package pricing

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

// repoRoot walks up from this test file to the directory containing go.mod.
func repoRoot(t *testing.T) string {
	t.Helper()
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	dir := filepath.Dir(thisFile)
	for i := 0; i < 10; i++ {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	t.Fatal("go.mod not found above test directory")
	return ""
}
